package com.socialblog.interaction.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="interactions")public class Interaction{@Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="actor_id",nullable=false)private UUID actorId;@Enumerated(EnumType.STRING)@Column(name="target_type",nullable=false)private TargetType targetType;@Column(name="target_id",nullable=false)private UUID targetId;@Column(name="reaction_type")private String reactionType;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt=Instant.now();public Interaction(){}public Interaction(UUID actorId,TargetType targetType,UUID targetId,String reactionType){this.actorId=actorId;this.targetType=targetType;this.targetId=targetId;this.reactionType=reactionType;}public Interaction(UUID actorId,TargetType targetType,UUID targetId){this(actorId,targetType,targetId,"LIKE");}public UUID getId(){return id;}public UUID getActorId(){return actorId;}public TargetType getTargetType(){return targetType;}public UUID getTargetId(){return targetId;}public String getReactionType(){return reactionType;}public void setReactionType(String reactionType){this.reactionType=reactionType;}public Instant getCreatedAt(){return createdAt;}}
